const demo = { frames: 5742, gaps: 595, seconds: 106, unlocked: false, unlockAt: Date.now() + 25000 };

function demoState() {
  const ach = DEMO.live.map(a => Object.assign({}, a));
  const unlocks = [];

  if (demo.unlocked) {
    const a = ach.find(x => x.id === 261028); a.state = 2;
    unlocks.push({ id: 261028, title: 'Bring My Car Back... Now!', badge: '609319', points: 2,
                   ago: Math.floor((Date.now() - demo.unlockAt) / 1000) });
  }
  return {
    version: DEMO_VERSION,
    login: { ok: true, webapi: true, user: 'Hacan359' },
    console: { connected: true, ip: '192.168.1.142', status: 'active', packets: demo.frames * 2,
               frames: demo.frames, gaps: demo.gaps, dupes: 0, torn: 0,
               watch: { parts: 2, bytes: 1351, addresses: 490 }, seconds: Math.floor(demo.seconds) },
    game: { id: 5613, serial: 'SLUS_210.65', hash: 'f45e0a19d50c42dbf2870fa34ae708f4',
            title: 'Need for Speed: Underground 2', achievements: ach, tracking: [] },
    /* The console is here, so FOLLOW is off and LIVE belongs to the
       console: the same shape the client sends. */
    follow: { on: false, active: false },
    lan: { on: false, url: '' },
    unlocks
  };
}

function demoRoute(url, opts) {
  const [path, q] = url.split('?');
  const id = q ? Number(new URLSearchParams(q).get('id')) : 0;

  if (opts && opts.method === 'POST') return { ok: true };
  if (path === '/state') return demoState();
  if (path === '/library') return { games: DEMO.library };
  if (path === '/game') return DEMO.games[id] || { id, title: '', achievements: [] };
  if (path === '/boards') return { boards: DEMO.boards[id] || [] };
  if (path === '/profile') return DEMO.profile;
  return {};
}

const realFetch = window.fetch.bind(window);

window.fetch = (url, opts) => (typeof url === 'string' && url.startsWith('/'))
  ? Promise.resolve(new Response(JSON.stringify(demoRoute(url, opts)),
                                 { headers: { 'Content-Type': 'application/json' } }))
  : realFetch(url, opts);

window.EventSource = class {
  constructor() {
    const send = d => { if (this.onmessage) this.onmessage({ data: JSON.stringify(d) }); };

    setTimeout(() => send(demoState()), 50);
    setInterval(() => {
      demo.frames += 11 + Math.floor(Math.random() * 3); demo.seconds += 0.2;
      if (Math.random() < 0.1) demo.gaps += 1;
      if (!demo.unlocked && Date.now() >= demo.unlockAt) { demo.unlocked = true; send(demoState()); return; }
      send({ delta: 1, console: { frames: demo.frames, gaps: demo.gaps, dupes: 0, torn: 0,
                                  seconds: Math.floor(demo.seconds) }, live: [], tracking: [] });
    }, 200);
    setInterval(() => send(demoState()), 1000);
  }
  close() {}
};

/* QUIT would blank the page a visitor is reading. */
window.confirm = () => false;
